import java.util.*;

public class Main {

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();

        String[] a = new String[n]; // 作答
        String[] b = new String[n]; // 标准答案
        for (int i = 0; i < n; i++) {
            a[i] = sc.next();
        }
        for (int i = 0; i < n; i++) {
            b[i] = sc.next();
        }
        int res = 0;
        for (int i = 0; i < n; i++) {
            int count = 0;
            // 遍历“标准答案”中的每一个字符
            for (char x : a[i].toCharArray()) {
                // 看它是否在“作答”中出现
                for (char y : b[i].toCharArray()) {
                    if (x == y) {
                        count++;
                        break;
                    }
                }
            }
            // 如果“标准答案”的所有字符都在“作答”中出现
            if (count == a[i].length()) {
                if (b[i].length() <= a[i].length()) {   // 如果“标准答案”长度等于“作答”长度，则算全部正确，得 3 分
                    res += 3;
                } else {                                // 否则算作部分正确，得 1 分
                    res += 1;
                }
            }
            // 如果“标准答案”有一个字符在“作答”中未出现，则算作错误，不加分
        }
        System.out.println(res);
	}
}
