    # 统计 s[i] 中的字母在 t[i] 中出现的次数
    cnt = 0
    for ch in s[i]:
        if ch in t[i]:   # 检查字符是否存在于期望标记中
            cnt += 1
    # 如果 s[i] 的所有字母都在 t[i] 中出现
    if cnt == len(s[i]):
        # 部分正确：期望标记长度严格大于实际标记
        if len(t[i]) > len(s[i]):
            score += 1
        # 全对：长度相等且字母全覆盖，即完全相同
        else:
            score += 3
    # 否则 0 分（不操作）

print(score)
