import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        String[] s = new String[n];   // 实际标记
        String[] t = new String[n];   // 期望标记

        for (int i = 0; i < n; i++) {
            s[i] = sc.next();
        }
        for (int i = 0; i < n; i++) {
            t[i] = sc.next();
        }

        int total = 0;
        for (int i = 0; i < n; i++) {
            int cnt = 0;
            // 遍历实际标记的每个字符
            for (char ch : s[i].toCharArray()) {
                // 检查是否在期望标记中出现
                for (char ch2 : t[i].toCharArray()) {
                    if (ch == ch2) {
                        cnt++;
                        break;
                    }
                }
            }
            // 如果所有字符都出现
            if (cnt == s[i].length()) {
                if (t[i].length() > s[i].length()) {
                    total += 1;   // 部分正确
                } else {
                    total += 3;   // 全对（完全相同）
                }
            }
        }
        System.out.println(total);
        sc.close();
    }
}
